xml.Script:
        if not VarExists('K') then
            K := 0.7;
        if not VarExists('a') then
            a := 1;
        if not VarExists('b') then
            b := 0.3;
        if not VarExists('Nx') then
            Nx := 20;
        if not VarExists('Nz') then
            Nz := 20;

        for i := 0 to Nx - 1 do begin
            Ax := 2*Pi/Nx * i;
            cs[i] := cos(Ax);
            ss[i] := sin(Ax);
        end;

        // Egg's equation by Skallos from https://nyjp07.com/index_egg_E.html
        for j := 0 to Nz do begin
            M := tan(Pi/Nz/2 * j);
            Z[j] := -K * a * ((1 + M^2 * b) * 2 / (1 + M^2)^2 - a);
            R[j] := (-Z[j] + K * a) * M;
        end;
